import{_ as r,o as i,c as n,ah as a}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Die Klagsmaschine: Michael Rami und die Juristerei der Einschüchterung","description":"Vom Verfassungsrichter zum Medien-Henker: Wie Michael Rami das Recht nutzt, um Kritiker der Macht zum Schweigen zu bringen.","frontmatter":{"title":"Die Klagsmaschine: Michael Rami und die Juristerei der Einschüchterung","description":"Vom Verfassungsrichter zum Medien-Henker: Wie Michael Rami das Recht nutzt, um Kritiker der Macht zum Schweigen zu bringen.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-04-07-michael-rami-lawsuit-machine.md","filePath":"logbuch/2026-04-07-michael-rami-lawsuit-machine.md"}'),t={name:"logbuch/2026-04-07-michael-rami-lawsuit-machine.md"};function s(h,e,d,u,c,l){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="die-klagsmaschine-michael-rami-und-die-juristerei-der-einschuchterung" tabindex="-1">Die Klagsmaschine: Michael Rami und die Juristerei der Einschüchterung <a class="header-anchor" href="#die-klagsmaschine-michael-rami-und-die-juristerei-der-einschuchterung" aria-label="Permalink to &quot;Die Klagsmaschine: Michael Rami und die Juristerei der Einschüchterung&quot;">​</a></h1><p><strong>Wien, 7. April 2026</strong> – Während unser Projekt die 500.000er-Marke im Viralitäts-Index knackt, blicken wir auf einen Akteur, der die Architektur der Macht im Hintergrund mit juristischer Härte absichert: <strong>Michael Rami</strong>.</p><p>In der Welt des „Horten-Mysteriums“ gibt es nicht nur Geld und Politik, es gibt auch die „Säuberer“, die dafür sorgen, dass unangenehme Fragen teuer werden. Sehr teuer.</p><h2 id="der-verfassungsrichter-als-abmahn-profi" tabindex="-1">Der Verfassungsrichter als Abmahn-Profi <a class="header-anchor" href="#der-verfassungsrichter-als-abmahn-profi" aria-label="Permalink to &quot;Der Verfassungsrichter als Abmahn-Profi&quot;">​</a></h2><p>Michael Rami ist ein Phänomen der österreichischen Sonderklasse. Er sitzt als von der FPÖ nominierter Richter am <strong>Verfassungsgerichtshof (VfGH)</strong> – dem heiligen Gral der Rechtsstaatlichkeit. Doch wenn er die Robe auszieht, schwingt er das juristische Beil für die politische Elite.</p><p>Besonders in Erinnerung: Die Klagswelle im Auftrag von <strong>Katharina Nehammer</strong>, der Frau des Bundeskanzlers.</p><ul><li><strong>Das Geschäftsmodell:</strong> Hunderte Privatpersonen, die ein (zugegeben falsches) Posting über Masken-Deals auf Facebook geteilt hatten, bekamen Post von Rami.</li><li><strong>Der Preis:</strong> Rund 4.500 Euro pro Person. Ein Klick, ein geteilter Beitrag – und schon steht die Existenz auf dem Spiel.</li><li><strong>Die Botschaft:</strong> Leg dich nicht mit der Kanzlerfamilie an. Kritik oder auch nur das Weiterverbreiten von Gerüchten wird zum finanziellen Genickbruch.</li></ul><h2 id="cobra-gate-und-die-mauer-des-schweigens" tabindex="-1">Cobra-Gate und die Mauer des Schweigens <a class="header-anchor" href="#cobra-gate-und-die-mauer-des-schweigens" aria-label="Permalink to &quot;Cobra-Gate und die Mauer des Schweigens&quot;">​</a></h2><p>Rami ist der Mann fürs Grobe, wenn es darum geht, Gerüchte einzufrieren. Ob es um die alkoholisierten Cobra-Beamten im Hause Nehammer geht oder um die Verstrickungen rund um <em>Hygiene Austria</em> – Ramis Strategie ist immer dieselbe: <strong>Juristische Eskalation.</strong></p><p>Anstatt durch Transparenz zu glänzen, setzt das System auf Einschüchterung. Wer es wagt, die „Schweinereien“ (wie es im Volksmund heißt) beim Namen zu nennen, findet sich vor Gericht wieder, gegenübergestellt einem Mann, der tagsüber über die Verfassung wacht.</p><h2 id="die-analogie-schaufenster-und-paragraphen" tabindex="-1">Die Analogie: Schaufenster und Paragraphen <a class="header-anchor" href="#die-analogie-schaufenster-und-paragraphen" aria-label="Permalink to &quot;Die Analogie: Schaufenster und Paragraphen&quot;">​</a></h2><p>Helmut Horten kontrollierte die Schaufenster der Konsumwelt. Michael Rami kontrolliert die Schaufenster der öffentlichen Meinung durch Paragraphen. In unserem Projekt symbolisiert er den <strong>„Pointillismus der Paragraphen“</strong>: Jede Klage ist ein kleiner Punkt, der am Ende ein Bild der Angst erzeugt.</p><p>Wir integrieren diesen Typus des „System-Anwalts“ in <strong>Teil 4 unseres Drehbuchs</strong>. Er ist derjenige, der die Akten nicht verbrennt, sondern sie hinter einer Mauer aus Klagsdrohungen verschließt.</p><p><em>Der Index steigt. Die Justiz mahlt. Wir dokumentieren.</em></p><hr><p>👈 <a href="/logbuch/">Zurück zum Logbuch</a> 🔮 <a href="/orakel.html">Das Orakel nach der Gerechtigkeit befragen</a></p>',16)])])}const m=r(t,[["render",s]]);export{g as __pageData,m as default};
